def _validate_request(data, signature):
    """Validate the request's required fields and signature.

    A missing payload is a malformed request, while a missing or unverifiable
    signature is an authentication failure.  Keeping these checks together
    ensures that no request reaches ``process`` before it has been validated.
    """
    if data is None:
        raise ValueError("request data is required")

    if signature is None:
        raise PermissionError("missing signature")

    if not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate a signed request and process its payload."""
    _validate_request(data, signature)
    return process(data)

